using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com";

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var client = new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential());
        return client.GetChatClient(DeploymentName).AsIChatClient();
    }

    public static ReportingConfiguration CreateReportingConfig(
        string storagePath = "eval-results")
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var chatConfig = new ChatConfiguration(CreateChatClient);
        var storage = new DiskBasedReportingStorage(storagePath);

        return new ReportingConfiguration(
            storage,
            chatConfig,
            evaluators,
            enableTelemetry: true);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that AI interactions produce traced,
/// structured evaluation data stored for reporting.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalConfig.CreateReportingConfig("eval-results/telemetry");
    }

    [TestMethod]
    public async Task CoachResponse_IsTracedAndScored()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_IsTracedAndScored));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "Explain the builder pattern in C# with a short example."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        scenario.Record(response);
        await scenario.EvaluateAsync(response, additionalContext:
            [new EvaluationContext("grounding",
                "The builder pattern separates construction of a complex object from its representation.")]);
    }

    [TestMethod]
    public async Task CoachResponse_MultiTurn_IsTraced()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MultiTurn_IsTraced));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "What is dependency injection?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        scenario.Record(response);

        messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));
        messages.Add(new ChatMessage(ChatRole.User, "Give me a simple example in C#."));

        var followUp = await chatClient.GetResponseAsync(messages);
        scenario.Record(followUp);

        await scenario.EvaluateAsync(followUp, additionalContext:
            [new EvaluationContext("grounding",
                "Dependency injection is a design pattern where dependencies are provided to a class rather than created internally.")]);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: asserts that AI responses meet minimum quality thresholds
/// for coherence, relevance, fluency, and groundedness.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalConfig.CreateReportingConfig("eval-results/quality");
    }

    [TestMethod]
    public async Task CoachAdvice_MeetsQualityThresholds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachAdvice_MeetsQualityThresholds));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "How should I structure a .NET solution with multiple services?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        scenario.Record(response);

        var results = await scenario.EvaluateAsync(response, additionalContext:
            [new EvaluationContext("grounding",
                "A well-structured .NET solution separates concerns into projects for API, domain, infrastructure, and tests.")]);

        AssertQualityScores(results);
    }

    [TestMethod]
    public async Task CoachAdvice_TechnicalExplanation_MeetsQualityThresholds()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachAdvice_TechnicalExplanation_MeetsQualityThresholds));

        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "Explain async/await in C# and when to avoid it."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        scenario.Record(response);

        var results = await scenario.EvaluateAsync(response, additionalContext:
            [new EvaluationContext("grounding",
                "Async/await enables non-blocking I/O in C#. Avoid it for CPU-bound work or when the overhead exceeds the benefit.")]);

        AssertQualityScores(results);
    }

    private static void AssertQualityScores(EvaluationResult results)
    {
        const double MinScore = 3.0;

        Assert.IsTrue(
            results.Get<NumericMetric>(CoherenceEvaluator.CoherenceMetricName).Value >= MinScore,
            $"Coherence score below {MinScore}");

        Assert.IsTrue(
            results.Get<NumericMetric>(RelevanceEvaluator.RelevanceMetricName).Value >= MinScore,
            $"Relevance score below {MinScore}");

        Assert.IsTrue(
            results.Get<NumericMetric>(FluencyEvaluator.FluencyMetricName).Value >= MinScore,
            $"Fluency score below {MinScore}");

        Assert.IsTrue(
            results.Get<NumericMetric>(GroundednessEvaluator.GroundednessMetricName).Value >= MinScore,
            $"Groundedness score below {MinScore}");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario against multiple model configurations
/// and stores results side-by-side for comparison via the reporting dashboard.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string[] Deployments =
        (Environment.GetEnvironmentVariable("EVAL_COMPARE_DEPLOYMENTS") ?? "gpt-4o-mini,gpt-4o")
        .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

    [TestMethod]
    public async Task CompareModels_CoachResponse()
    {
        var prompt = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "What are the SOLID principles? Summarize each in one sentence."),
        };

        var groundingContext = new EvaluationContext("grounding",
            "SOLID: Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion.");

        foreach (var deployment in Deployments)
        {
            var config = EvalConfig.CreateReportingConfig($"eval-results/compare/{deployment}");

            await using var scenario = await config.CreateScenarioRunAsync(
                scenarioName: $"{nameof(CompareModels_CoachResponse)}_{deployment}");

            var chatClient = scenario.ChatClient!;
            var response = await chatClient.GetResponseAsync(prompt);

            scenario.Record(response);
            await scenario.EvaluateAsync(response, additionalContext: [groundingContext]);
        }
    }

    [TestMethod]
    public async Task CompareModels_CodeGeneration()
    {
        var prompt = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coding coach."),
            new(ChatRole.User, "Write a C# method that checks if a string is a palindrome."),
        };

        var groundingContext = new EvaluationContext("grounding",
            "A palindrome reads the same forwards and backwards. Compare the string with its reverse.");

        foreach (var deployment in Deployments)
        {
            var config = EvalConfig.CreateReportingConfig($"eval-results/compare/{deployment}");

            await using var scenario = await config.CreateScenarioRunAsync(
                scenarioName: $"{nameof(CompareModels_CodeGeneration)}_{deployment}");

            var chatClient = scenario.ChatClient!;
            var response = await chatClient.GetResponseAsync(prompt);

            scenario.Record(response);
            await scenario.EvaluateAsync(response, additionalContext: [groundingContext]);
        }
    }
}

